SELECT 'winners_below_0.2pct' AS metric, COUNT(*) AS n, SUM(pp.realized_pnl) AS pnl FROM crypto_ai.paper_position pp WHERE pp.status IN ('CLOSED','STOPPED') AND pp.realized_pnl > 0 AND pp.realized_pnl / NULLIF(pp.entry_price * pp.quantity, 0) * 100 < 0.2 UNION ALL SELECT 'all_winners', COUNT(*), SUM(pp.realized_pnl) FROM crypto_ai.paper_position pp WHERE pp.status IN ('CLOSED','STOPPED') AND pp.realized_pnl > 0 UNION ALL SELECT 'buy_1m_then_bearish_next_1m', SUM(n.decision IN ('SELL','STRONG_SELL')), COUNT(*) FROM crypto_ai.trade_signal b JOIN crypto_ai.trade_signal n ON n.symbol = b.symbol AND n.interval_code = '1m' AND n.candle_open_time = b.candle_open_time + INTERVAL 1 MINUTE WHERE b.interval_code = '1m' AND b.decision IN ('BUY','STRONG_BUY') AND b.candle_open_time BETWEEN '2026-10-11 00:00:00' AND '2026-10-13 00:00:00' LIMIT 10